/**
 * «Итоги года» (1.7): экраны-истории и картинка PNG в одних цветах в обеих темах.
 * Картинку рисует canvas, поэтому цвета здесь простыми значениями, а в CSS из них собран градиент.
 */
export const recapColors = {
  from: '#0F2A1E',
  to: '#0A0A0A',
  accent: '#34D27B',
  text: '#EDEDED',
  sub: 'rgba(237,237,237,0.62)',
  card: 'rgba(255,255,255,0.08)',
};

/** Мини-плеер (1.8): три вида, размеры окна. */
export const miniSizes = {
  bar: { width: 360, height: 136 }, // горизонтальный: обложка, название, прогресс, управление
  lyrics: { width: 300, height: 520 }, // вертикальный с текстом песни
  cover: { width: 260, height: 260 }, // только обложка (при наведении поверх управление)
} as const;
export type MiniMode = keyof typeof miniSizes;

